33	/* 
34	 * Only modify PCB, current_running, process_id and ready_queue
35	 * DO NOT STORE OR RESTORE 
36	 * trick: modify $tp in ret_from_exception to ensure
37	 * disable_preempt() and enable_preempt() modify the same PCB
38	 */
39	void scheduler(void)
40	{
41	    pcb_t *cur_running = current_running[cpu_id];
42	
43	    /* put the current task back to the ready queue if it is still runnable
44	     * (the kernel pcbs of both harts are never queued) */
45	    if(cur_running->status == TASK_RUNNING){
46	        cur_running->status = TASK_READY;
47	        cur_running->ready_tick = get_ticks();
48	        if(cur_running->pid != 0){
49	            list_add_tail(&cur_running->list, &ready_queue);
50	        }
51	    }
52	
53	    /* pick the highest priority task allowed to run on this core;
54	     * run the kernel pcb of this core if there is no such task */
55	    list_node_t *next_node = max_priority_node();
56	    pcb_t *next_running;
57	    if(next_node == NULL){
58	        next_running = &kernel_pcb[cpu_id];
59	    }
60	    else{
61	        list_del(next_node);
62	        next_running = list_entry(next_node, pcb_t, list);
63	    }
64	
65	    next_running->status = TASK_RUNNING;
66	    next_running->cpu_id = cpu_id;
67	    current_running[cpu_id] = next_running;
68	    current_cpu_running = next_running;
69	}
