71	pid_t do_spawn(task_info_t *task, void* arg, spawn_mode_t mode)
72	{
73	    disable_preempt();
74	
75	    /* search for a free pcb */
76	    int i;
77	    for(i = 0; i < NUM_MAX_TASK; i++){
78	        if(pcb[i].pid == -1){
79	            break;
80	        }
81	    }
82	    if(i == NUM_MAX_TASK){
83	        enable_preempt();
84	        return -1;
85	    }
86	
87	    pcb_t *new_pcb = &pcb[i];
88	
89	    /* allocate the kernel stack and the user stack */
90	    new_pcb->kernel_sp = allocPage(1);
91	    new_pcb->user_sp = allocPage(1);
92	    new_pcb->preempt_count = 0;
93	    new_pcb->kernel_stack_base = new_pcb->kernel_sp;
94	    new_pcb->user_stack_base = new_pcb->user_sp;
95	
96	    list_add_tail(&new_pcb->list, &ready_queue);
97	    init_list_head(&new_pcb->wait_list);
98	    new_pcb->binsem_num = 0;
99	
100	    new_pcb->pid = process_id++;
101	    new_pcb->type = task->type;
102	    new_pcb->status = TASK_READY;
103	    new_pcb->mode = mode;
104	    new_pcb->priority = task->priority;
105	    new_pcb->ready_tick = get_ticks();
106	    new_pcb->mask = 3;
107	    new_pcb->cursor_x = 0;
108	    new_pcb->cursor_y = 0;
109	
110	    /* initialization registers: ra, sp, gp, a0, sstatus, sepc, sscratch */
111	    regs_context_t *pt_regs = (regs_context_t *)(new_pcb->kernel_sp - sizeof(regs_context_t));
112	    new_pcb->kernel_sp -= sizeof(regs_context_t);
113	    pt_regs->regs[1] = (reg_t)task->entry_point;   //ra
114	    pt_regs->regs[2] = (reg_t)new_pcb->user_sp;    //sp
115	    pt_regs->regs[3] = (reg_t)__global_pointer$;   //gp
116	    pt_regs->regs[10] = (reg_t)arg;                //a0
117	    pt_regs->sstatus = (reg_t)SR_SPIE;             //SPP = 0, SPIE = 1
118	    pt_regs->sepc = (reg_t)task->entry_point;      //sepc
119	    pt_regs->sscratch = (reg_t)new_pcb;            //sscratch = tp
120	
121	    enable_preempt();
122	    return new_pcb->pid;
123	}
