125	/* release all the binsems held by `p`, waking up one waiter per binsem */
126	static void release_binsems(pcb_t *p)
127	{
128	    for(int i = 0; i < p->binsem_num; i++){
129	        int binsem_id = p->binsem_id[i];
130	        binsem_node_t *node = &binsem_nodes[binsem_id];
131	        node->sem++;
132	        if(node->sem <= 0 && !list_empty(&node->block_queue)){
133	            list_node_t *unblocked_node = node->block_queue.next;
134	            pcb_t *unblocked_pcb = list_entry(unblocked_node, pcb_t, list);
135	            unblocked_pcb->binsem_id[unblocked_pcb->binsem_num] = binsem_id;
136	            unblocked_pcb->binsem_num++;
137	            do_unblock(unblocked_node);
138	        }
139	    }
140	    p->binsem_num = 0;
141	}
