143	void do_exit()
144	{
145	    disable_preempt();
146	
147	    pcb_t *exit_pcb = current_running[cpu_id];
148	
149	    /* release all the binsems held by this task */
150	    release_binsems(exit_pcb);
151	
152	    /* release the user stack */
153	    freePage(exit_pcb->user_stack_base, 1);
154	
155	    /* wake up all the tasks waiting for this task */
156	    while(!list_empty(&exit_pcb->wait_list)){
157	        do_unblock(exit_pcb->wait_list.next);
158	    }
159	
160	    if(exit_pcb->mode == ENTER_ZOMBIE_ON_EXIT){
161	        /* become a zombie, `do_waitpid` will release the kernel stack */
162	        exit_pcb->status = TASK_ZOMBIE;
163	    }
164	    else{
165	        /* hand the pcb over to the kernel for cleanup */
166	        exit_pcb->status = TASK_EXITED;
167	        list_add_tail(&exit_pcb->list, &kernel_pcb[0].wait_list);
168	    }
169	
170	    /* reschedule because the current_running is exited */
171	    scheduler();
172	    enable_preempt();
173	}
