187	int do_kill(pid_t pid)
188	{
189	    disable_preempt();
190	
191	    /* search the pcb */
192	    pcb_t *kill_pcb = NULL;
193	    for(int i = 0; i < NUM_MAX_TASK; i++){
194	        if(pcb[i].pid == pid){
195	            kill_pcb = &pcb[i];
196	            break;
197	        }
198	    }
199	    if(kill_pcb == NULL){
200	        enable_preempt();
201	        return 0;
202	    }
203	
204	    /* remove the task from its queue (ready / blocked / sleep);
205	     * a no-op if the task is running and thus not queued */
206	    list_del(&kill_pcb->list);
207	
208	    /* release all the binsems held by this task */
209	    release_binsems(kill_pcb);
210	
211	    /* release the user stack */
212	    freePage(kill_pcb->user_stack_base, 1);
213	
214	    /* wake up all the tasks waiting for this task */
215	    while(!list_empty(&kill_pcb->wait_list)){
216	        do_unblock(kill_pcb->wait_list.next);
217	    }
218	
219	    if(kill_pcb->mode == ENTER_ZOMBIE_ON_EXIT){
220	        kill_pcb->status = TASK_ZOMBIE;
221	    }
222	    else{
223	        kill_pcb->status = TASK_EXITED;
224	        list_add_tail(&kill_pcb->list, &kernel_pcb[0].wait_list);
225	    }
226	
227	    /* reschedule if the task killed itself */
228	    if(kill_pcb == current_running[cpu_id]){
229	        scheduler();
230	    }
231	
232	    enable_preempt();
233	    return 1;
234	}
