236	int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, regs_context_t *regs)
237	{
238	    disable_preempt();
239	
240	    /* search the pcb */
241	    pcb_t *wait_pcb = NULL;
242	    for(int i = 0; i < NUM_MAX_TASK; i++){
243	        if(pcb[i].pid == pid){
244	            wait_pcb = &pcb[i];
245	            break;
246	        }
247	    }
248	    if(wait_pcb == NULL){
249	        enable_preempt();
250	        return 0;
251	    }
252	
253	    /* block until the target task exits */
254	    if(wait_pcb->status != TASK_ZOMBIE && wait_pcb->status != TASK_EXITED){
255	        do_block(&current_running[cpu_id]->list, &wait_pcb->wait_list);
256	        scheduler();
257	    }
258	
259	    /* reap the zombie: release the pcb and the kernel stack
260	     * (only the first woken waiter does this) */
261	    if(wait_pcb->status == TASK_ZOMBIE){
262	        wait_pcb->status = TASK_EXITED;
263	        wait_pcb->pid = -1;
264	        freePage(wait_pcb->kernel_stack_base, 1);
265	    }
266	
267	    enable_preempt();
268	    return pid;
269	}
