426	// block the pcb task into the block queue
427	void do_block(list_node_t *pcb_node, list_head *queue)
428	{
429	    list_del(pcb_node);
430	    list_add_tail(pcb_node, queue);
431	    list_entry(pcb_node, pcb_t, list)->status = TASK_BLOCKED;
432	}
