434	// unblock the `pcb` from the block queue
435	void do_unblock(list_node_t *pcb_node)
436	{
437	    list_del(pcb_node);
438	    list_add_tail(pcb_node, &ready_queue);
439	    list_entry(pcb_node, pcb_t, list)->status = TASK_READY;
440	    list_entry(pcb_node, pcb_t, list)->ready_tick = get_ticks();
441	}
