443	list_node_t* max_priority_node(void)
444	{
445	    list_node_t *max_node = NULL;
446	    pcb_t *max_pcb = NULL;
447	
448	    /* search the ready queue for the highest priority task whose
449	     * hart mask allows it to run on this core; the task that became
450	     * ready first wins among tasks with the same priority */
451	    for(list_node_t *node = ready_queue.next; node != &ready_queue; node = node->next){
452	        pcb_t *check_pcb = list_entry(node, pcb_t, list);
453	        if(!(check_pcb->mask & (1lu << cpu_id))){
454	            continue;
455	        }
456	        if(max_node == NULL ||
457	           check_pcb->priority > max_pcb->priority ||
458	           (check_pcb->priority == max_pcb->priority &&
459	            check_pcb->ready_tick < max_pcb->ready_tick)){
460	            max_node = node;
461	            max_pcb = check_pcb;
462	        }
463	    }
464	    return max_node;
465	}

