7	mailbox_t mailbox[MBOX_NUM];
8	int free_mailbox = 0;
9	message_t message[MBOX_NUM];
10	int message_status[MBOX_NUM] = {0};
11	
12	int do_mbox_open(char *name)
13	{
14	    /* search for an existing mailbox with the same name */
15	    for(int i = 0; i < MBOX_NUM; i++){
16	        if(!kstrcmp(name, mailbox[i].name)){
17	            message_t *cur_message = &message[mailbox[i].id];
18	            (cur_message->opned)++;
19	            return mailbox[i].id;
20	        }
21	    }
22	
23	    // create a new mailbox
24	    int id;
25	    for(int i = 0; i < MBOX_NUM; i++){
26	        if(!message_status[i]){
27	            id = i;
28	            break;
29	        }
30	    }
31	    mailbox_t *new_mailbox = &mailbox[free_mailbox++];
32	    kstrcpy(new_mailbox->name, name);
33	    new_mailbox->id = id;
34	
35	    // init the message
36	    message_t *new_message = &message[id];
37	    message_status[id] = 1;
38	    init_list_head(&new_message->wait_queue);
39	    new_message->opned = 1;
40	    new_message->msg[0] = '\0';
41	    new_message->msg_len = 0;
42	
43	    return new_mailbox->id;
44	}
45	
46	void do_mbox_close(int mailbox_id)
47	{
48	    message_t *closed_message = &message[mailbox_id];
49	    (closed_message->opned)--;
50	    if(closed_message->opned == 0){
51	        message_status[mailbox_id] = 0;
52	    }
53	}
54	
55	int do_mbox_send(int mailbox_id, void *msg, int msg_length)
56	{
57	    message_t *cur_message = &message[mailbox_id];
58	    if(cur_message->msg_len + msg_length >= MAX_MBOX_LENGTH){
59	        // the mailbox is full, block and retry next time
60	        do_block(&current_running[cpu_id]->list, &cur_message->wait_queue);
61	        scheduler();
62	        return 0;
63	    }
64	    else{
65	        kmemcpy((char*)&(cur_message->msg[cur_message->msg_len]), (char*)msg, msg_length);
66	        cur_message->msg_len += msg_length;
67	        // wake up the blocked receivers
68	        while(!list_empty(&cur_message->wait_queue)){
69	            do_unblock(cur_message->wait_queue.next);
70	        }
71	        scheduler();
72	        return 1;
73	    }
74	}
75	
76	int do_mbox_recv(int mailbox_id, void *msg, int msg_length)
77	{
78	    message_t *cur_message = &message[mailbox_id];
79	    if(msg_length > cur_message->msg_len){
80	        // the mailbox is empty, block and retry next time
81	        do_block(&current_running[cpu_id]->list, &cur_message->wait_queue);
82	        scheduler();
83	        return 0;
84	    }
85	    else{
86	        cur_message->msg_len -= msg_length;
87	        kmemcpy((char*)msg, (char*)&(cur_message->msg[cur_message->msg_len]), msg_length);
88	        // wake up the blocked senders
89	        while(!list_empty(&cur_message->wait_queue)){
90	            do_unblock(cur_message->wait_queue.next);
91	        }
92	        scheduler();
93	        return 1;
94	    }
95	}

