6	
7	binsem_node_t binsem_nodes[BINSEM_NUMBER];
8	
9	// a simple hash function
10	static int binsem_hash(uint64_t x)
11	{
12	    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ul;
13	    x = (x ^ (x >> 27)) * 0x94d049bb133111ebul;
14	    x = x ^ (x >> 31);
15	    return x % BINSEM_NUMBER;
16	}
17	
18	void init_system_binsem()
19	{
20	    for(int i = 0; i < BINSEM_NUMBER; i++){
21	        binsem_nodes[i].sem = 1;
22	        init_list_head(&binsem_nodes[i].block_queue);
23	    }
24	}
25	
26	int binsem_get(int key)
27	{ 
28	    return binsem_hash((uint64_t)key);
29	}
30	
31	void binsem_op(int binsem_id, int op)
32	{
33	    disable_preempt();
34	
35	    binsem_node_t *node = &binsem_nodes[binsem_id];
36	
37	    if(op == BINSEM_OP_LOCK){
38	        node->sem--;
39	        if(node->sem < 0){
40	            do_block(&current_running[cpu_id]->list, &node->block_queue);
41	            scheduler();
42	        }
43	        else{
44	            /* record the binsem held by this process,
45	             * so that `do_exit` can release it */
46	            current_running[cpu_id]->binsem_id[current_running[cpu_id]->binsem_num] = binsem_id;
47	            current_running[cpu_id]->binsem_num++;
48	        }
49	    }
50	    else if(op == BINSEM_OP_UNLOCK){
51	        node->sem++;
52	        current_running[cpu_id]->binsem_num--;
53	        if(node->sem <= 0){
54	            /* hand the binsem over to the first waiter */
55	            list_node_t *unblocked_pcb_list = node->block_queue.next;
56	            pcb_t *unblocked_pcb = list_entry(unblocked_pcb_list, pcb_t, list);
57	            unblocked_pcb->binsem_id[unblocked_pcb->binsem_num] = binsem_id;
58	            unblocked_pcb->binsem_num++;
59	            do_unblock(unblocked_pcb_list);
60	            scheduler();
61	        }
62	    }
63	
64	    enable_preempt();
65	}

