151	    time_base = sbi_read_fdt(TIMEBASE);
152	    timer_interval = (uint64_t)(time_base / 100);
153	
154	    // init Process Control Block
155	    init_pcb();
156	    printk("> [INIT] PCB initialization succeeded.\n\r");
157	
158	    // init futex mechanism and binsem mechanism
159	    init_system_futex();
160	    init_system_binsem();
161	
162	    // init interrupt
163	    init_exception();
164	    printk("> [INIT] Interrupt processing initialization succeeded.\n\r");
165	
166	    // init system call table
167	    init_syscall();
168	    printk("> [INIT] System call initialized successfully.\n\r");
169	
