171	    init_screen();
172	    printk("> [INIT] SCREEN initialization succeeded.\n\r");
173	    
174	    spin_lock_init(&kernel_lock);
175	
176	    // wakeup another core
177	    wakeup_other_hart();
178	 
179	    // Setup timer interrupt and enable all interrupt
180	    enable_interrupt();
181	    setup_exception();
182	    sbi_set_timer(get_ticks() + timer_interval);
183	
184	    while (1){
185	        disable_preempt();
186	        list_node_t* clean_node = kernel_pcb[0].wait_list.next;
187	        while(clean_node != &kernel_pcb[0].wait_list){
188	            pcb_t *clean_pcb = list_entry(clean_node, pcb_t, list);
189	            // release pcb
190	            clean_pcb->status = TASK_EXITED;
191	            clean_pcb->pid = -1;
192	            // release kernel stack
193	            freePage(clean_pcb->kernel_stack_base, 1);
194	            
195	            clean_node = clean_node->next;
196	            list_del(clean_node->prev);
197	        }
198	    
199	        enable_preempt();
200	        __asm__ __volatile__("wfi\n\r":::);
201	    }
202	}

