42	// double-linked list
43	typedef struct list_node
44	{
45	    struct list_node *next, *prev;
46	} list_node_t;
47	
48	typedef list_node_t list_head;
49	
50	#define offsetof(TYPE, MEMBER) ((size_t) &((TYPE *)0)->MEMBER)
51	#define list_entry(ptr, type, member)                    \
52	    ({                                                     \
53	        const typeof(((type *)0)->member) *__mptr = (ptr); \
54	        (type *)((char *)__mptr - offsetof(type, member)); \
55	    })
56	
57	// LIST_HEAD is used to define the head of a list.
58	#define LIST_HEAD(name) struct list_node name = {&(name), &(name)}
59	
60	static inline void init_list_head(list_head *list)
61	{
62	    list->next = list;
63	    list->prev = list;
64	}
65	
66	static inline void _list_add(
67	    list_node_t *node, list_node_t *prev, list_node_t *next)
68	{
69	    next->prev = node;
70	    node->next = next;
71	    node->prev = prev;
72	    prev->next = node;
73	}
74	
75	static inline void _list_del(list_node_t *prev, list_node_t *next)
76	{
77	    next->prev = prev;
78	    prev->next = next;
79	}
80	static inline void list_del(list_node_t *entry)
81	{
82	    if (entry->prev != NULL && entry->next != NULL) {
83	        _list_del(entry->prev, entry->next);
84	        entry->prev = NULL;
85	        entry->next = NULL;
86	    }
87	}
88	
