7	
8	#define MAX_RANGE 5000000
9	#define MOD 1000007
10	#define NUM_CPUS 2
11	
12	struct TestMultiCoreArg
13	{
14	    int print_location;
15	    int from;
16	    int to;
17	    int* result;
18	};
19	void add_task(struct TestMultiCoreArg* args);
