21	void test_multicore(void)
22	{
23	    sys_move_cursor(1, 1);
24	    printf("start test multi-core performance\n\r");
25	    int single_core_result = 0;
26	    struct task_info task_add = {(uintptr_t)&add_task, USER_PROCESS};
27	    struct TestMultiCoreArg singleCoreArg = {1, 0, MAX_RANGE, &single_core_result};
28	    // single core performance
29	    clock_t singleCoreBegin = clock();
30	    pid_t single_pid = sys_spawn(&task_add, (void*)&singleCoreArg, ENTER_ZOMBIE_ON_EXIT);
31	    sys_waitpid(single_pid);
32	    clock_t singleCoreEnd = clock();
33	    sys_move_cursor(1, 6);
34	    printf("single core: %ld ticks, result = %d            \n\r", singleCoreEnd - singleCoreBegin, single_core_result);
35	
36	    struct TestMultiCoreArg multiCoreArgs[NUM_CPUS];
37	    pid_t pids[NUM_CPUS];
38	    int multi_core_results[NUM_CPUS] = {0};
39	    for (int i = 0; i < NUM_CPUS; ++i) {
40	        multiCoreArgs[i].print_location = i + 2;
41	        multiCoreArgs[i].from = MAX_RANGE * i / NUM_CPUS;
42	        multiCoreArgs[i].to = MAX_RANGE * (i + 1) / NUM_CPUS;
43	        multiCoreArgs[i].result = &multi_core_results[i];
44	    }
45	
46	    clock_t multiCoreBegin = clock();
47	    for (int i = 0; i < NUM_CPUS; ++i) {
48	        pids[i] = sys_spawn(&task_add, (void*)&multiCoreArgs[i], ENTER_ZOMBIE_ON_EXIT);
49	    }
50	
51	    for (int i = 0; i < NUM_CPUS; ++i) {
52	        sys_waitpid(pids[i]);
53	    }
54	    int multi_core_final_result = 0;
55	    for (int i = 0; i < NUM_CPUS; ++i) {
56	        multi_core_final_result += multi_core_results[i];
57		    multi_core_final_result = multi_core_final_result % MOD;
58	    }
59	    clock_t multiCoreEnd = clock();
60	    sys_move_cursor(1, 7);
61	    printf("multi core: %ld ticks, result = %d             \n\r", multiCoreEnd - multiCoreBegin, multi_core_final_result);
62	
63	    sys_exit();
64	}
65	
66	void add_task(struct TestMultiCoreArg* args)
67	{
68	    int print_location = args->print_location;
69	    int from  = args->from;
70	    int to = args->to;
71	    int result = 0;
72	
73	    sys_move_cursor(1, print_location);
74	    printf("start compute, from = %d, to = %d  ", from, to);
75	    for (int i = from; i < to; ++i) {
76	        result = (result + i) % MOD;
77	    }
78	    printf("Done \n\r");
79	    *args->result = result;
80	    sys_exit();
81	}

